const repo = "acme/api";

// Collect all open issues labelled "bug" (paginated).
const all: any[] = [];
for (let page = 1; page <= 50; page++) {
  const r: any = await tools.list_issues({ repo, state: "open", label: "bug", page });
  const items: any[] = Array.isArray(r) ? r : (r?.items ?? r?.issues ?? r?.data ?? []);
  if (!items.length) break;
  all.push(...items);
  if (items.length < 50) break;
}

const hasBugLabel = (i: any) =>
  (i.labels ?? []).some((l: any) => (typeof l === "string" ? l : l?.name) === "bug");

const isUnassigned = (i: any) => {
  if (i.assignee) return false;
  if (Array.isArray(i.assignees) && i.assignees.length > 0) return false;
  return true;
};

const countComments = async (num: number): Promise<number> => {
  let n = 0;
  for (let page = 1; page <= 50; page++) {
    const r: any = await tools.list_comments({ repo, number: num, page });
    const items: any[] = Array.isArray(r) ? r : (r?.items ?? r?.comments ?? r?.data ?? []);
    n += items.length;
    if (items.length < 50) break;
  }
  return n;
};

const details: any[] = [];
let count = 0;
for (const summary of all) {
  const num = summary.number;
  // Fetch full issue to get reliable assignee/comment data.
  const full: any = await tools.get_issue({ repo, number: num });
  const issue = full?.issue ?? full ?? summary;
  const labelsOk = hasBugLabel(issue) || hasBugLabel(summary) || (issue.labels == null && summary.labels == null);
  const state = (issue.state ?? summary.state ?? "open").toString().toLowerCase();
  if (state !== "open" || !labelsOk) continue;
  if (!isUnassigned(issue) || !isUnassigned(summary)) continue;

  let comments: number | undefined =
    typeof issue.comments === "number" ? issue.comments
    : typeof issue.comments_count === "number" ? issue.comments_count
    : typeof issue.comment_count === "number" ? issue.comment_count
    : typeof summary.comments === "number" ? summary.comments
    : undefined;
  if (comments === undefined) comments = await countComments(num);

  details.push({ number: num, comments });
  if (comments > 5) count++;
}

console.log("open bug issues fetched:", all.length);
console.log("sample shape:", JSON.stringify(all[0] ?? null).slice(0, 600));
console.log("candidates (unassigned, open, bug):", JSON.stringify(details).slice(0, 2000));
return { count };
